"""Check first-party license metadata; dependency evidence is generated by each build."""
# SPDX-FileCopyrightText: 2026 jfk1987 and GameHub contributors
# SPDX-License-Identifier: AGPL-3.0-only
import json
from pathlib import Path


def check(root):
    if (root / 'LICENSE').read_bytes() != (root / 'licensing/LICENSE').read_bytes():
        raise ValueError('The distributed AGPL text differs from the root LICENSE')
    for folder, license in [('frontend', 'AGPL-3.0-only'), ('docs/site', 'MIT')]:
        package = json.loads((root / folder / 'package.json').read_text())
        lock = json.loads((root / folder / 'package-lock.json').read_text())
        if package.get('license') != license or lock['packages'][''].get('license') != license:
            raise ValueError(f'Inconsistent license metadata: {folder}')
    print('Project license metadata is consistent; dependency notices are generated from resolved build inputs.')


if __name__ == '__main__':
    check(Path(__file__).resolve().parents[2])
